});

Then('the edit input for {string} has focus', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      const editInput = li.querySelector('.edit');
      expect(this.document.activeElement).to.equal(editInput);
      break;
