Then('the todo {string} does not exist', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  expect(found).to.be.false;
});

Then('the todo {string} has the editing class', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      const li = label.closest('li');
      expect(li.classList.contains('editing')).to.be.true;
