});

Then('the todo {string} still exists', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  const found = Array.from(labels).some(l => l.textContent === title);
  expect(found).to.be.true;
});

Then('the localStorage key {string} contains an array with {int} item', function (key, count) {
  const stored = this.window.localStorage.getItem(key);
  const arr = JSON.parse(stored);
  expect(arr.length).to.equal(count);
});

Then('the first item in localStorage {string} has title {string}', function (key, title) {
  const stored = this.window.localStorage.getItem(key);
  const arr = JSON.parse(stored);
  expect(arr[0].title).to.equal(title);
});

Then('the first item in localStorage {string} has id {int}', function (key, id) {
