  const arr = JSON.parse(stored);
  expect(arr[1].id).to.equal(id);
});

// ── DOM-identity steps ───────────────────────────────────────────────────
// These steps hold ACTUAL DOM element references across actions, so they
// detect the defect where render() destroys and recreates <li> nodes
// (innerHTML = '') instead of mutating them in place.

When('the user notes the DOM node for todo {string}', function (title) {
  const labels = this.document.querySelectorAll('.todo-list label');
  for (const label of labels) {
    if (label.textContent === title) {
      this._trackedLi = label.closest('li');
      return;
    }
  }
  throw new Error(`Todo "${title}" not found in the DOM`);
});

When('the user notes the first DOM node in the list', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length === 0) throw new Error('No todo items in the list');
  this._trackedLi = items[0];
});

When('the user notes all {int} DOM nodes in the list', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length !== count) throw new Error(`Expected ${count} items, got ${items.length}`);
  this._trackedLis = Array.from(items);
});

Then('the tracked DOM node is still the same element', function () {
  expect(this._trackedLi).to.exist;
  // Walk up to the parent and check that the tracked node is still a direct child.
  // If render() destroyed and recreated it, the original reference would be orphaned
  // and this check would fail.
  const parent = this._trackedLi.parentNode;
  expect(parent).to.exist;
  const stillPresent = Array.from(parent.childNodes).some(child => child === this._trackedLi);
  expect(stillPresent).to.be.true;
});

Then('the tracked DOM nodes are still the same elements', function () {
  expect(this._trackedLis).to.exist;
  const items = this.document.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(this._trackedLis.length);
  for (let i = 0; i < this._trackedLis.length; i++) {
    const tracked = this._trackedLis[i];
    const parent = tracked.parentNode;
    expect(parent).to.exist;
    const stillPresent = Array.from(parent.childNodes).some(child => child === tracked);
    expect(stillPresent).to.be.true;
  }
});

// ── Routing back-button step ──────────────────────────────────────────────

When('the user presses the browser back button', function () {
  this.window.history.back();
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

// ── Browser-acceptance defect steps ──────────────────────────────────────

// Fires blur THEN keydown(Enter) on the edit input, reproducing the real-browser
// event sequence when a user presses Enter while the input is focused.
// In a real browser both events fire; the double-destroy causes removeChild to
// fail. This step lets the in-harness suite exercise the same path.
When('the user clears the edit input and fires blur and Enter together', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  editInput.value = '';
  // Blur fires first in real browsers, then keydown(Enter)
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode: 13, bubbles: true }));
});

// Asserts that no <li> in the todo list has the 'editing' class.
Then('no todo is in editing mode', function () {
  const editingItems = this.document.querySelectorAll('.todo-list li.editing');
  expect(editingItems.length).to.equal(0);
});

// Presses browser back WITHOUT manually dispatching hashchange.
// In a real browser history.back() fires hashchange synchronously.
// In happy-dom the hash changes but hashchange fires asynchronously,
// so the app may not re-render in time — reproducing the real defect.
When('the user presses the browser back button without manual hashchange', function () {
  this.window.history.back();
  // Do NOT dispatch hashchange — let the browser/happy-dom handle it naturally.
});

// Clicks a filter link by its visible text ("All", "Active", or "Completed").
When('the user clicks the {string} filter link', function (name) {
  const links = this.document.querySelectorAll('.filters a');
  for (const link of links) {
    if (link.textContent === name) {
      link.click();
      return;
    }
  }
  throw new Error(`Filter link "${name}" not found`);
});

// Asserts the current window.location.hash.
Then('the window hash is {string}', function (expectedHash) {
  expect(this.window.location.hash).to.equal(expectedHash);
});

// ── Source-level conformance checks ──────────────────────────────────────

Given('the app source is loaded', function () {
  const fs = require('node:fs');
  const path = require('node:path');
  const appPath = path.resolve(__dirname, '..', '..', 'js', 'app.js');
  this._appSource = fs.readFileSync(appPath, 'utf8');
});

Then('the destroyTodo function clears the editingId variable', function () {
  // destroyTodo must clear editingId so re-entrant render does not re-attach the orphan.
  const source = this._appSource;
  // Find the destroyTodo function body
  const destroyStart = source.indexOf('function destroyTodo');
  if (destroyStart === -1) throw new Error('destroyTodo function not found in source');
  let braceDepth = 0; let inFunc = false; let funcEnd = destroyStart;
  for (let i = destroyStart; i < source.length; i++) {
    if (source[i] === '{') { braceDepth++; inFunc = true; }
    if (source[i] === '}') { braceDepth--; if (inFunc && braceDepth === 0) { funcEnd = i; break; } }
  }
  const destroyMatch = { 1: source.substring(destroyStart, funcEnd + 1) };
  if (!destroyMatch) throw new Error('destroyTodo function not found in source');
  const body = destroyMatch[1];
  const clearsEditingId = /editingId\s*=\s*null/.test(body);
  expect(clearsEditingId, 'destroyTodo must clear editingId to prevent re-attachment of orphaned nodes during re-entrant render (blur during removeChild)').to.be.true;
});

Then('the orphan-removal guard in render checks parentNode equals todoList', function () {
  // The orphan-removal loop must reject nodes whose parent has changed — not merely
  // check parentNode is truthy.  In a real browser, re-entrant blur during removeChild
  // can re-attach the orphan to a different parent; a truthy-only guard passes, and
  // removeChild then throws NotFoundError because the parent is no longer todoList.
  // The guard must compare parentNode to todoList (the .todo-list container).
  const source = this._appSource;
  const startIdx = source.indexOf('existingLis[j]');
  if (startIdx === -1) throw new Error('orphan-removal loop over existingLis not found');
  // Grab 400 chars around the guard — enough to capture the if-condition
  const loopSection = source.substring(Math.max(0, startIdx - 100), startIdx + 400);
  // Must contain an if-condition that references BOTH parentNode and todoList
  const hasTodoListComparison = /parentNode\s*===\s*todoList|todoList\s*===\s*parentNode/.test(loopSection);
  expect(hasTodoListComparison, 'The orphan-removal guard must compare parentNode to todoList (e.g. existingLis[j].parentNode === todoList), not merely check parentNode is truthy. A truthy-only guard fails when re-entrant blur re-attaches the orphan to a different parent.').to.be.true;
});

Then('the render function contains a parentNode guard in the orphan-removal loop', function () {
  // The orphan-removal loop in render() must guard against detached nodes.
  // In a real browser, re-entrant blur during removeChild causes the node
  // to be detached before the loop reaches it. The guard checks parentNode
  // before calling removeChild, preventing the NotFoundError.
  const source = this._appSource;
  // Find the orphan-removal loop: it iterates existingLis and calls removeChild
  const hasOrphanLoop = /existingLis\[j\]/.test(source);
  expect(hasOrphanLoop, 'Source must contain an orphan-removal loop over existingLis').to.be.true;
  // Extract the orphan-removal loop block (from existingLis[j] to the closing brace)
  const startIdx = source.indexOf('existingLis[j]');
  const loopSection = source.substring(startIdx, startIdx + 500);
  // The guard must CHECK parentNode in a conditional BEFORE removeChild.
  // A bare `existingLis[j].parentNode.removeChild(...)` is NOT a guard.
  // We need to find: if (... parentNode ...) { ... removeChild ... }
  // Split the loop section into lines and check if there's an if-condition referencing parentNode
  const lines = loopSection.split('\n');
  let foundGuard = false;
  for (const line of lines) {
    // Match an if/while condition that mentions parentNode
    if (/\bif\s*\(.*parentNode.*\)/.test(line) || /\bwhile\s*\(.*parentNode.*\)/.test(line)) {
      foundGuard = true;
      break;
    }
  }
  expect(foundGuard, 'The orphan-removal loop must contain a conditional (if/while) that explicitly tests parentNode before calling removeChild — e.g. if (existingLis[j].parentNode) { existingLis[j].parentNode.removeChild(...) }. A bare parentNode.removeChild without a guard does not prevent NotFoundError during re-entrant blur').to.be.true;
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Preserve localStorage across reloads
  _savedStorage = null;

  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // Save localStorage before creating new window
    if (this.window) {
      this._savedStorage = {};
      for (let i = 0; i < this.window.localStorage.length; i++) {
        const key = this.window.localStorage.key(i);
        this._savedStorage[key] = this.window.localStorage.getItem(key);
      }
    }

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Restore saved localStorage
    if (this._savedStorage) {
      for (const [key, value] of Object.entries(this._savedStorage)) {
        this.window.localStorage.setItem(key, value);
      }
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
